<div class="heading"><div><h1>Webmail</h1><p>Read and send messages through your configured mail server.</p></div><a class="button secondary" href="/dashboard">Dashboard</a></div>
<?php if($error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endif; ?>
<?php if(isset($_GET['sent'])): ?><p class="notice">Message accepted by the SMTP server.</p><?php endif; ?>
<?php if(isset($_GET['moved'])): ?><p class="notice">Message moved.</p><?php endif; ?><?php if(isset($_GET['draft'])): ?><p class="notice">Draft saved to the IMAP server.</p><?php endif; ?><?php if(isset($_GET['flagged'])): ?><p class="notice">Message flags updated.</p><?php endif; ?>
<?php if(!$mailboxes): ?><section class="panel"><p>No active mailbox is assigned to your account.</p></section><?php else: ?>
<section class="panel">
<form method="get" action="/mail" class="toolbar"><label>Mailbox<select name="mailbox" onchange="this.form.submit()"><?php foreach($mailboxes as $m): ?><option value="<?= (int)$m['id'] ?>" <?= (int)($activeMailbox['id']??($_GET['mailbox']??0))===(int)$m['id']?'selected':'' ?>><?= htmlspecialchars($m['email'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><label>Search<input name="q" value="<?= htmlspecialchars($query, ENT_QUOTES, 'UTF-8') ?>" maxlength="200" placeholder="Search this folder"></label><button type="submit">Search</button></form>
<?php if($activeMailbox): ?>
<div class="mail-layout">
<aside class="folder-list"><h2>Folders</h2><?php foreach($folders as $folder): ?><a class="<?= $folder['name']===$selectedFolder?'active':'' ?>" href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($folder['name']) ?>"><?= htmlspecialchars($folder['name'], ENT_QUOTES, 'UTF-8') ?></a><?php endforeach; ?></aside>
<section class="message-column"><h2><?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?></h2>
<?php if(!$messages): ?><p class="muted">This folder is empty.</p><?php else: ?><div class="message-list"><?php foreach($messages as $message): ?><a class="message-row <?= $message['seen']?'':'unread' ?>" href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$message['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?>"><span><?= htmlspecialchars($message['from'], ENT_QUOTES, 'UTF-8') ?></span><strong><?= !empty($message['flagged']) ? '★ ' : '' ?><?= htmlspecialchars($message['subject'], ENT_QUOTES, 'UTF-8') ?></strong><time><?= htmlspecialchars($message['date'], ENT_QUOTES, 'UTF-8') ?></time></a><?php endforeach; ?></div><?php endif; ?>
<nav class="mail-pagination"><?php if($page>1): ?><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&page=<?= $page-1 ?>&q=<?= rawurlencode($query) ?>">Newer messages</a><?php endif; ?><?php if($hasMore): ?><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&page=<?= $page+1 ?>&q=<?= rawurlencode($query) ?>">Older messages</a><?php endif; ?></nav>
<?php if($selectedMessage): ?><article class="panel message-detail"><h2><?= htmlspecialchars($selectedMessage['subject'], ENT_QUOTES, 'UTF-8') ?></h2><p><strong>From:</strong> <?= htmlspecialchars($selectedMessage['from'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>To:</strong> <?= htmlspecialchars($selectedMessage['to'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>Date:</strong> <?= htmlspecialchars($selectedMessage['date'], ENT_QUOTES, 'UTF-8') ?></p><p class="message-actions"><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$selectedMessage['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?>&compose=reply">Reply</a><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$selectedMessage['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?>&compose=forward">Forward</a></p><pre><?= htmlspecialchars($selectedMessage['body'], ENT_QUOTES, 'UTF-8') ?></pre><div class="message-actions"><form method="post" action="/mail/flag"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="flag" value="Flagged"><input type="hidden" name="enabled" value="<?= !empty($selectedMessage['flagged']) ? '0' : '1' ?>"><button class="secondary small"><?= !empty($selectedMessage['flagged']) ? 'Remove star' : 'Star message' ?></button></form><form method="post" action="/mail/flag"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="flag" value="Seen"><input type="hidden" name="enabled" value="0"><button class="secondary small">Mark unread</button></form></div><?php if(!empty($selectedMessage['attachments'])): ?><section class="attachments"><h3>Attachments</h3><ul><?php foreach($selectedMessage['attachments'] as $attachment): ?><li><a href="/mail/attachment?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$selectedMessage['uid'] ?>&section=<?= rawurlencode($attachment['section']) ?>"><?= htmlspecialchars($attachment['filename'], ENT_QUOTES, 'UTF-8') ?></a> <small><?= number_format(((int)$attachment['size'])/1024, 1) ?> KB</small></li><?php endforeach; ?></ul></section><?php endif; ?><?php $folderNames = array_column($folders, 'name'); $trash = in_array('Trash', $folderNames, true) ? 'Trash' : (in_array('Deleted Items', $folderNames, true) ? 'Deleted Items' : ''); $spam = in_array('Spam', $folderNames, true) ? 'Spam' : (in_array('Junk', $folderNames, true) ? 'Junk' : ''); ?>
<?php foreach (['Trash' => $trash, 'Spam' => $spam] as $label => $destination): ?><?php if($destination): ?><form method="post" action="/mail/move" class="inline"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="source" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="destination" value="<?= htmlspecialchars($destination, ENT_QUOTES, 'UTF-8') ?>"><button class="<?= $label==='Trash'?'danger':'secondary' ?> small">Move to <?= $label ?></button></form><?php endif; ?><?php endforeach; ?></article><?php endif; ?>
</section></div>
<?php else: ?><p class="muted">Select an active mailbox to continue.</p><?php endif; ?></section>
<?php if($activeMailbox): ?><section class="panel compose"><h2>Compose</h2><form method="post" action="/mail/send" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="in_reply_to" value="<?= htmlspecialchars($compose['in_reply_to'], ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="references" value="<?= htmlspecialchars($compose['references'], ENT_QUOTES, 'UTF-8') ?>"><label>From<input readonly value="<?= htmlspecialchars($activeMailbox['email'], ENT_QUOTES, 'UTF-8') ?>"></label><label>To<input name="to" value="<?= htmlspecialchars($compose['to'], ENT_QUOTES, 'UTF-8') ?>" placeholder="recipient@example.com (separate multiple recipients with commas)"></label><label>Subject<input name="subject" value="<?= htmlspecialchars($compose['subject'], ENT_QUOTES, 'UTF-8') ?>" maxlength="998"></label><label>Plain-text message<textarea name="body" rows="8" placeholder="Plain-text version"><?= htmlspecialchars($compose['body'], ENT_QUOTES, 'UTF-8') ?></textarea></label><label>Optional HTML message<textarea name="html_body" rows="6" placeholder="Optional HTML alternative"></textarea></label><label>Attachments<input type="file" name="attachments[]" multiple><small>Up to 10 files; 25 MB total</small></label><button type="submit">Send message</button> <button type="submit" class="secondary" formaction="/mail/draft">Save draft</button></form></section><?php endif; ?>
<?php endif; ?>
